import os
import sqlite3
import sys
from typing import Optional

VAULT_DB = os.getenv('VAULT_DB', 'vault.db')

def compute_verifier(value: str) -> str:
    return hash(value) % (2**32)

def initialize_db():
    conn = sqlite3.connect(VAULT_DB)
    cursor = conn.cursor()
    cursor.execute('''
        CREATE TABLE IF NOT EXISTS records (
            name TEXT PRIMARY KEY,
            kind TEXT NOT NULL,
            verifier INTEGER NOT NULL
        )
    ''')
    conn.commit()
    conn.close()

def put(conn, name: str, kind: str, value: str):
    verifier = compute_verifier(value)
    cursor = conn.cursor()
    cursor.execute('''
        INSERT OR REPLACE INTO records (name, kind, verifier)
        VALUES (?, ?, ?)
    ''', (name, kind, verifier))
    conn.commit()

def check(conn, name: str, candidate: str):
    cursor = conn.cursor()
    cursor.execute('''
        SELECT verifier FROM records WHERE name = ?
    ''', (name,))
    result = cursor.fetchone()
    if result is None:
        print('NO')
        return
    stored_verifier = result[0]
    computed_verifier = compute_verifier(candidate)
    if stored_verifier == computed_verifier:
        print('OK')
    else:
        print('NO')

def find(conn, column: str, op: str, value: str):
    cursor = conn.cursor()
    if column == 'name':
        if op == '=':
            cursor.execute('SELECT name, kind FROM records WHERE name = ?', (value,))
        elif op == 'PREFIX':
            cursor.execute('SELECT name, kind FROM records WHERE name LIKE ?', (f'%{value}%',))
    elif column == 'kind':
        if op == '=':
            cursor.execute('SELECT name, kind FROM records WHERE kind = ?', (value,))
        elif op == 'PREFIX':
            cursor.execute('SELECT name, kind FROM records WHERE kind LIKE ?', (f'%{value}%',))
    results = cursor.fetchall()
    for name, kind in sorted(results, key=lambda x: x[0]):
        print(f"{name}|{kind}")

def main():
    initialize_db()
    conn = sqlite3.connect(VAULT_DB)
    for line in sys.stdin:
        line = line.strip()
        if not line:
            continue
        parts = line.split()
        if len(parts) < 3:
            continue
        command = parts[0]
        if command == 'put':
            if len(parts) != 4:
                continue
            name, kind, value = parts[1], parts[2], ' '.join(parts[3:])
            put(conn, name, kind, value)
        elif command == 'check':
            if len(parts) != 3:
                continue
            name, candidate = parts[1], ' '.join(parts[2:])
            check(conn, name, candidate)
        elif command == 'find':
            if len(parts) != 4:
                continue
            column, op, value = parts[1], parts[2], ' '.join(parts[3:])
            find(conn, column, op, value)
    conn.close()

if __name__ == '__main__':
    main()
